import{bQ as e,aL as a,u as n,G as s}from"./chunks/framework.C1gZXFVa.js";const c=JSON.parse('{"title":"充提改账协同","description":"充提与调账如何进入撮合改账通道，与挂单占用串行争用同一份可用/冻结。","frontmatter":{"title":"充提改账协同","description":"充提与调账如何进入撮合改账通道，与挂单占用串行争用同一份可用/冻结。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070511"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070511"}],["meta",{"property":"og:title","content":"充提改账协同 · TGEX"}],["meta",{"property":"og:description","content":"充提与调账如何进入撮合改账通道，与挂单占用串行争用同一份可用/冻结。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"充提改账协同 · TGEX"}],["meta",{"name":"twitter:description","content":"充提与调账如何进入撮合改账通道，与挂单占用串行争用同一份可用/冻结。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"充提改账协同\\",\\"description\\":\\"充提与调账如何进入撮合改账通道，与挂单占用串行争用同一份可用/冻结。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070511\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070511\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070511.md","filePath":"07.现货手册/05.核心流程/11.充提改账协同.md"}'),r={name:"pages/070511.md"};function p(o,t,i,d,l,h){return a(),n("div",null,[...t[0]||(t[0]=[s(`<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="充提改账协同" tabindex="-1">充提改账协同 <a class="header-anchor" href="#充提改账协同" aria-label="Permalink to &quot;充提改账协同&quot;">​</a></h1><div class="doc-lead">链上充提、人工调账等由账务侧发起；要影响现货交易可用余额，必须进入撮合改账通道，与下单 / 成交 / 撤单争同一份热钱包。本页只写**与撮合的协同**，不写钱包扫块与审核细节。</div><p>链上出入金步骤见<a href="/pages/1003">钱包 · 核心充提流程</a>；划转 / 冻结语义见<a href="/pages/0602">核心资金流程</a>；撮合热钱包结构见<a href="/pages/070802">用户币币账户缓存</a>。</p><h2 id="为什么必须进撮合" tabindex="-1">为什么必须进撮合 <a class="header-anchor" href="#为什么必须进撮合" aria-label="Permalink to &quot;为什么必须进撮合&quot;">​</a></h2><p>现货 V1 下，<strong>交易当下可用 / 冻结的权威在撮合进程内存</strong>。若充提只改 MySQL 或只改账务库、不通知撮合：</p><ul><li>用户已到账，交易页仍显示旧可用 → 误拒单</li><li>或页面已加钱、撮合未加 → 可能超卖占用</li></ul><p>因此架构图上的「余额同步」虚线，指的是：<strong>账务事实 → 消息 → 撮合改账事件 → 热缓存</strong>。</p><h2 id="协同路径" tabindex="-1">协同路径 <a class="header-anchor" href="#协同路径" aria-label="Permalink to &quot;协同路径&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>充提 / 调账在账务侧确认</span></span>
<span class="line"><span>    → 消息队列（或等价通知）</span></span>
<span class="line"><span>    → 撮合非交易对改账通道</span></span>
<span class="line"><span>    → 与该用户币种相关的事件串行处理</span></span>
<span class="line"><span>    → 改写用户币币账户缓存（可用增减等）</span></span>
<span class="line"><span>    → 异步落缓冲 / 流水旁路</span></span></code></pre></div><p>要点：</p><ol><li><strong>不挡下单主链</strong>：用户点下单时，不会先同步堵在账务「充提完成」接口上；到账是旁路对齐。</li><li><strong>与交易事件同链串行</strong>：改可用与挂单冻结抢同一格子，避免「一边充值加可用、一边下单冻可用」交叉写花。</li><li><strong>装入只补洞</strong>：格子已在内存则以内存为准；缺失时才回源，见账户缓存文档。</li></ol><p>账务服务自身如何就绪（在线改账、批处理扫流水），见<a href="/pages/070506">账务初始化链路</a>。</p><h2 id="和交易主路径的关系" tabindex="-1">和交易主路径的关系 <a class="header-anchor" href="#和交易主路径的关系" aria-label="Permalink to &quot;和交易主路径的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>谁改热钱包</th><th>是否占订单簿</th></tr></thead><tbody><tr><td>下单冻结 / 成交划转 / 撤单解冻</td><td>撮合交易事件</td><td>是（下单 / 撤单）</td></tr><tr><td>充提到账 / 调账</td><td>撮合改账事件</td><td>否</td></tr><tr><td>手续费暂存累计</td><td>成交事件内</td><td>间接（随成交）</td></tr></tbody></table><p>页面上「余额变了」可能来自充提到账，也可能来自成交或撤单；权威仍以撮合热缓存（协同完成后）为准。对账层次见<a href="/pages/0603">对账与资金一致性</a>。</p><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对照</th><th>说明</th></tr></thead><tbody><tr><td><a href="/pages/1003">钱包 · 核心充提流程</a></td><td>链上确认、审核、入账发起</td></tr><tr><td><a href="/pages/070506">账务初始化链路</a></td><td>账务工程就绪</td></tr><tr><td><a href="/pages/070508">撮合主流程</a></td><td>交易事件如何改同一钱包</td></tr><tr><td><a href="/pages/0702">系统架构</a></td><td>虚线「余额同步」在图上的位置</td></tr><tr><td>商户结算打款、法币出入金</td><td>不展开</td></tr></tbody></table><p>同组：<a href="/pages/070802">用户币币账户缓存</a> · <a href="/pages/070506">账务初始化链路</a> · <a href="/pages/0702">系统架构</a> · <a href="/pages/0602">核心资金流程</a></p>`,19)])])}const m=e(r,[["render",p]]);export{c as __pageData,m as default};
